declare module '@semantic-release/release-notes-generator' {
  interface GenerateNotesCommit {
    hash: string;
    message: string;
  }

  interface GenerateNotesLogger {
    log(...args: unknown[]): void;
    error(...args: unknown[]): void;
  }

